WITH model as (
  SELECT
    {{field}},
    COUNT(*) as model_rowcount
  FROM
    {{model}}
  WHERE 1=1
    {% if row_condition is not none %}AND {{row_condition}}{% endif %}
  GROUP BY {{field}}

),
compare_model as (
  SELECT
      {{compare_field}},
      COUNT(*) as compare_model_row_count
  FROM
    {{compare_model}}
  WHERE 1=1
    {% if compare_row_condition is not none %}AND {{compare_row_condition}}{% endif %}
  GROUP BY {{compare_field}}
)

SELECT
    model.{{field}} as model_{{field}},
    compare_model.{{compare_field}} as compare_model_{{compare_field}},
    model_rowcount,
    compare_model_row_count,
    IFNULL(model_rowcount, 0) - IFNULL(compare_model_row_count, 0) as diff,
    '{{model}}' as model_name,
    '{{compare_model}}' as compare_model_name
FROM
    model
    FULL OUTER JOIN compare_model
    ON model.{{field}} = compare_model.{{compare_field}}
WHERE ABS(diff) > 0
ORDER BY ABS(diff) desc


{% endtest %}

